/* ============ 宝可梦列表 ============ */
var spFilter={types:{}},spShown=0,spStep=120;
/* v4.78 P1：形态筛选开关（Mega / 最终形态）——并入 spMatch 同源链，图鉴/队伍构建/分析选择器三处同结果 */
var fOpt={mega:0,final:0};
function isMegaForm(s){return /^(超级|原始|究极)/.test(s.zh||'')}   /* 与形态名清洗同源（行1678 前缀集） */
/* ===== v4.289：ER 改版特色（全站单一开关） =====
   用户口径：「筛出 er 改版特色，包括所有 mega 形态（不用管是不是改版新增）和 er 新增形态或者宝可梦」。
   判定（三条任一命中）：
     ① 所有 Mega 类形态：中文名以「超级/原始/究极」开头，或含「原始回归」「究极爆发」，或英文名含 Mega
        —— 原版 Mega 与 ER 自创 Mega 一视同仁，不做「是否改版新增」的二次判断；
     ② Redux 专属形态：英文名含 Redux（如 Bulbasaur Redux / Mega Garchomp Redux）；
     ③ ER 原创宝可梦：中文名以 R 结尾（大钢蛇R/Carbonix、盐石巨灵R/Gargablox 这类，官方图鉴里没有）。
   官方各世代普通形态与地区形态（阿罗拉/洗翠等）**不算**特色。
   只影响列表呈现，不改任何判定口径与持久状态。 */
var ER_FLAVOR_KEY='er_flavor_v1';
function erFlavorOn(){try{return localStorage.getItem(ER_FLAVOR_KEY)==='1'}catch(eFz){return false}}
function isErFlavorSp(s){
  if(!s)return false;
  var zh=String(s.zh||''),en=String(s.en||'');
  if(/^(超级|原始|究极)/.test(zh))return true;
  if(/原始回归|究极爆发/.test(zh))return true;
  if(/\bMega\b/i.test(en))return true;   /* 词边界：避免 Meganium 这类只含「Mega」子串的普通宝可梦误入 */
  if(/\bRedux\b/i.test(en))return true;
  if(/R$/.test(zh))return true;
  return false;
}
function erFlavorOk(s){return !erFlavorOn()||isErFlavorSp(s)}
function flavorCountText(){
  var n=0;
  try{ERDATA.species.forEach(function(s){if(isErFlavorSp(s))n++})}catch(eFc){n=0}
  return n+' 只';
}
function erFlavorToggle(){
  var b=document.getElementById('erFlavorBox');
  var on=b?!!b.checked:!erFlavorOn();
  try{localStorage.setItem(ER_FLAVOR_KEY,on?'1':'0')}catch(eFz2){eFz2.name}
  var tag=document.getElementById('erFlavorCnt');
  if(tag)tag.textContent=on?('· '+flavorCountText()):'';
  try{renderSp(true)}catch(eR1){eR1.name}
  try{if(window.drawCoreList)window.drawCoreList()}catch(eR2){eR2.name}
  try{speedRender(true)}catch(eR3){eR3.name}
  try{renderMv()}catch(eR4){eR4.name}
  try{renderAbi()}catch(eR5){eR5.name}
  try{renderTm(true)}catch(eR6){eR6.name}
  try{renderAnalyze()}catch(eR7){eR7.name}
  try{if(window.renderAnPickerGrid)renderAnPickerGrid(true)}catch(eR8){eR8.name}
  toast(on?('已筛 ER 特色：只剩 Mega 形态 + Redux/ER 原创（'+flavorCountText()+'）'):'已取消 ER 特色筛选（回到全图鉴）');
}
(function(){
  function init(){
    var b=document.getElementById('erFlavorBox');
    if(b)b.checked=erFlavorOn();
    var tag=document.getElementById('erFlavorCnt');
    if(tag)tag.textContent=erFlavorOn()?('· '+flavorCountText()):'';
  }
  if(typeof ERDATA!=='undefined'&&ERDATA&&ERDATA.species)init();
  else document.addEventListener('er-ready',init);
})();
function renderSpFormChips(){
  var box=$('spFormChips');if(!box)return;box.innerHTML='';
  /* v4.78 fix：fOpt 切换后联动刷新队伍构建网格 + 分析选择器，保证三处 spQuery 结果集即时一致 */
  function _refreshAll(){
    renderSp(true);
    try{if($('tmGrid'))renderTm(true)}catch(eT){}
    try{if($('anpGrid'))renderAnPickerGrid(true)}catch(eA){}
  }
  /* v4.254：文案与核心配队页 #coreMega 对齐 —— 原「Mega 形态优先」没说清是「隐藏」，用户以为是排序 */
  box.appendChild(tchip('Mega 形态优先（隐藏可 Mega 的普通形态）',!!fOpt.mega,function(){fOpt.mega=!fOpt.mega;renderSpFormChips();_refreshAll()}));
  box.appendChild(tchip('仅最终形态',!!fOpt.final,function(){fOpt.final=!fOpt.final;renderSpFormChips();_refreshAll()}));
  /* v4.256：开关开了却没反应，是因为看不到「过滤掉了什么」。这里把隐去的条数摊到明面上。 */
  var note=$('spFilterNote');
  if(note){
    var msgs=[];
    var _rdy=(window.ERDATA&&ERDATA.species&&ERDATA.species.length>0);
    if(_rdy&&fOpt.mega){
      var nMega=Object.keys(hasMegaSet()).length;
      msgs.push('已隐藏 <b>'+nMega+'</b> 只「有 Mega 但本身不是 Mega」的普通形态（如喷火龙、超梦只剩超级形态）');
    }
    if(_rdy&&fOpt.final){
      var nNF=Object.keys(nonFinalSet()).length, nAll=ERDATA.species.length;
      msgs.push('已隐藏 <b>'+nNF+'</b> 只非最终形态（'+(nAll-nNF)+' / '+nAll+' 可见）');
    }
    note.innerHTML = msgs.length ? ('<span style="color:var(--accent);font-weight:600">筛选已生效</span>　'+msgs.join('　')) : '';
  }
}
function renderSpChips(){
  var box=$('spTypeChips');box.innerHTML='';
  ERDATA.types.forEach(function(t){
    box.appendChild(tchip(t,!!spFilter.types[t],function(){
      spFilter.types[t]=!spFilter.types[t];
      if(!spFilter.types[t])delete spFilter.types[t];
      /* 交集筛选：宝可梦仅双属性，最多保留 2 个选中（超限时取消最早选的） */
      var on=ERDATA.types.filter(function(x){return spFilter.types[x]});
      if(on.length>2)delete spFilter.types[on[0]];
      renderSpChips();renderSp(true);
    }));
  });
}
