/* v4.186：复合特性拆解 —— desc 形如 "A+B"（纯特性名拼接）时返回各子特性 {zh,id,desc}；
   任一项索引不到就返回 null（宁可不展开，也不误判为复合特性） */
/* v4.186：子特性名容错 —— 数据层个别名字与 ABI 规范名差一个字（如 440 写成「变换自如」、规范名「变幻自如」）。
   规则收紧：仅「长度相同、逐字比较只差 1 字、且全库唯一」时采用，否则放弃（宁可漏拆也不误拆）。 */
function abiFuzzyId(part){
  if(!part||part.length<3)return null;
  var best=null,cnt=0,plen=part.length;
  for(var k in ABI){
    var z=ABI[k][2];
    if(!z||z.length!==plen)continue;
    var d=0;
    for(var i=0;i<plen;i++){ if(z.charAt(i)!==part.charAt(i)){ d++; if(d>1)break; } }
    if(d<=1){ cnt++; if(cnt>1)return null; best=k; }
  }
  return cnt===1?best:null;
}
/* v4.186：从特性描述里抽出「被提及的招式名」。两类句式：
   ①入场型「入场时使用/释放 XX」；②触发型「使用X属性招式后触发/追加 XX」。
   抽出来后只做一件事：交给 mvIdByZhOrEn 精确匹配，命中才展示该招式的效果（命中不到就整块不显示）。 */
function abiCleanMvName(desc){
  if(!desc)return '';
  var d=(''+desc);
  var m=/(?:入场|上场|出场|替换上场)[^，。;\n]{0,8}?(?:使用|释放|施放|发动|放出|自动使用)([^，。;（(、\n]{2,14})/.exec(d);
  if(!m)m=/(?:触发|追加)([^，。;（(、\n]{2,16})/.exec(d);
  if(!m)return '';
  var t=m[1].trim();
  for(var i=0;i<4;i++){
    var n=t.replace(/^[一二三四五六七八九十百]+[格次发]/,'').replace(/^(?:威力|持续|约|共)?(?:\d+(?:\.\d+)?)(?:%|回合|威力|点)?的?/,'').replace(/^的/,'').trim();
    if(n===t)break;
    t=n;
  }
  return t.replace(/[.。,，]+$/,'').trim();
}
function abiCompositeBreak(desc){
  if(!desc||desc.indexOf('+')<0||desc.indexOf('\n')>=0)return null;
  var parts=desc.split('+').map(function(s){return s.trim()}).filter(function(s){return s});
  if(parts.length<2)return null;
  var out=[];
  for(var i=0;i<parts.length;i++){
    var hit=abiIdByZhOrEn(parts[i]);
    if(hit==null)hit=abiFuzzyId(parts[i]);
    if(hit==null)return null;
    var a=ABI[''+hit];
    out.push({zh:(a&&a[2])||parts[i],id:hit,desc:(a&&a[3])||''});
  }
  return out;
}
/* v4.186：源码级特性详解表 —— 只收「数据层描述不足以说明机制」的条目。
   依据一律为 ER 官方源码 Eliteredux/eliteredux-source（include/constants/abilities.h 与 src/battle_util.c），
   不写推测。rows 第 2 列走 glossify（纯文本，禁 HTML 标签，glossify 内部先 esc）。 */
