  if(FUNC_MV.removal.indexOf(mid)>-1)hz.push(mid===229?'除钉·高速旋转（清自身侧）':'除钉·清除浓雾（清双方）');
  if(hz.length)html+='<div style="margin:4px 0;font-size:14.5px">机制标签：'+hz.map(function(x){return '<span class="abi">'+x+'</span>'}).join(' ')+'</div>';
  if(mid===432)html+='<div style="margin:4px 0;font-size:14.5px">除钉范围：清双方钉子 · 墙仅对手侧 · 降闪避 1 级</div>';
  if(cst.tags.length)html+='<div style="margin:4px 0;font-size:14.5px"><b>代价标签：</b>'+cst.tags.map(function(x){return '<span class="badge badge-pend">'+esc(x)+'</span>'}).join(' ')+
    (cst.note?'<div style="font-size:13.5px;color:var(--sub)">'+esc(cst.note)+'</div>':'')+'</div>';
  html+='<div class="sec"><h3>谁能学 <span style="font-weight:400;font-size:13.5px;color:var(--sub)" id="mvLkCnt"></span></h3>'+
    '<div class="lkfilter"><label><input type="checkbox" id="mvFiltFinal"'+(optMvFinal?' checked':'')+' onchange="mvLookupRender(true)"> 仅最终形态</label>'+
    '<label><input type="checkbox" id="mvFiltMega"'+(optMvMega?' checked':'')+' onchange="mvLookupRender(true)"> Mega 形态优先（过滤可 Mega 的非 Mega）</label></div>'+
    '<div id="mvLearners"></div></div>';
  var _mvt=$('mvDrawerTitle'); if(_mvt)_mvt.textContent=String(m[1]||'招式详情'); /* v4.6-C：弹窗标题显示所选招式名 */
