/* ============ v4.94 结束 ============ */
function removeFromTeamById(id){
  for(var i=0;i<team.length;i++)if(team[i].id==id){removeFromTeam(team[i]);return}
}
/* 导出当前队伍配置文本（含勾选特性模拟方案） */
function exportTeam(){
  if(!team.length){toast('队伍为空，先加入或导入宝可梦');return}
  var lines=[];
  team.forEach(function(s){
    var info=teamInfo[s.id]||{};
    var pick=info.pick||'—';
    var mv=info.moves||[];
    var movesStr=mv.length?mv.join('/'):'—';
    var item=info.item?(' @'+info.item):'';
    var typesStr=s.t1+(s.t2&&s.t2!==s.t1?(' '+s.t2):'');
    lines.push(s.zh+' '+typesStr+' ['+pick+'] '+movesStr+item);
  });
  var txt=lines.join('\n');
  var ta=document.createElement('textarea');
  ta.value=txt;ta.style.position='fixed';ta.style.left='-9999px';
  document.body.appendChild(ta);ta.select();
  var ok=false;
  try{ok=document.execCommand('copy')}catch(e){}
  document.body.removeChild(ta);
  if(ok)toast('已复制队伍配置（'+team.length+' 只）到剪贴板');   /* v4.83 P2-2：导出成功轻反馈（此前 toast 携带整段配置文本，视觉噪音大；成功提示独立可见） */
  else{prompt('复制以下队伍配置文本：',txt)}
}
function pickAbi(id,idx){
  var s=null;
  team.forEach(function(x){if(x.id==id)s=x});
  if(!s)return;
  var info=teamInfo[s.id]=teamInfo[s.id]||{fromSave:false};
  if(idx===-1){info.pick=null}
  else{
    var n=s.abis[idx];
    if(!n)return;
    info.pick=(info.pick===n)?null:n;
  }
  renderSlots();renderAnalyze();saveTeam();
}
/* ============ 特性修正评估（v3：整体聚合——属性×天性×可选特性） ============ */
var IMMUNE_RISK={}; /* 属性 -> 常见免疫特性名（进攻警示用） */
ERDATA.abilities.forEach(function(a){
  var g=ERDATA.abiTags[a[0]];
  if(g&&g.im)g.im.forEach(function(t){(IMMUNE_RISK[t]=IMMUNE_RISK[t]||[]).push(a[2]||a[1])});
});
/* v4.244 别名归一：本表原用数据层 `a[2]`（abilities 中文名）作展示/比对名，而唯一的结构化消费点
   axisStateOf 用 `names.indexOf(x)>-1` 严格比对物种表名 ⇒ 别名差让「轴联防件」判定静默失效，文案也显示错名。
   注意 species 是分片异步注入（data_lite 只带 abilities/moves），本行执行时 ERDATA.species 尚不存在，
   故**不能**在此处直接扫 species（会把整段脚本抛错中断，实测 ER_ENGINE_VER 变 undefined）；
   改为在 er-ready 后重映射为物种表口径：abiIdC(nm) → id → abis/abiIds 同索引取真名。
   实测影响面：axisDetect 69 只变化（主轴 44 只），deriveBuilds 与 coreAbiPick 均 0 变化。 */
function ___immRiskRemap(){
  try{
    if(!window.ERDATA||!ERDATA.species||!ERDATA.species.length)return false;
    var id2={};
    ERDATA.species.forEach(function(x){
      if(!x)return;
      (x.abiIds||[]).forEach(function(id,k){var n=(x.abis||[])[k];if(id&&n&&!id2[id])id2[id]=n});
      (x.innIds||[]).forEach(function(id,k){var n=(x.inns||[])[k];if(id&&n&&!id2[id])id2[id]=n});
    });
    Object.keys(IMMUNE_RISK).forEach(function(t){
      IMMUNE_RISK[t]=IMMUNE_RISK[t].map(function(nm){var id=abiIdC(nm);return (id&&id2[id])?id2[id]:nm});
    });
    return true;
  }catch(e){return false}
}
if(document.addEventListener){document.addEventListener('er-ready',___immRiskRemap);};
/* v4.194：abiTags 漏登记的免疫类特性（源码 .onAbsorb + CHECK(moveType == TYPE_X) 逐个核对出来的）。
   ERDATA.abiTags 只有 107 条，这 7 个免疫特性没进去 → 工具会把它们算成「正常吃伤害」。
   「乘风(WIND_RIDER)」判的是 gBattleMoves[move].airBased（风系招式而非属性），无法用属性表达，不补。 */
var ABI_TAG_PATCH={
  '毒吸收':{im:['毒']},      /* src/abilities.cc:4446 POISON_ABSORB */
  '冰露':{im:['冰']},          /* :4823 ICE_DEW */
  '食土':{im:['地面']},        /* :5880 EARTH_EATER */
  '水库':{im:['水']},        /* :9290 RESERVOIR */
  '散热器':{im:['火']},        /* :10565 HEAT_SINK */
  '闪电形态':{im:['电']},      /* :10587 LIGHTNING_ASPECT */
  '熔核':{im:['岩石']},        /* :10734 MOLTEN_CORE（岩石，反直觉但源码 CHECK(moveType == TYPE_ROCK)） */
  '厚脂':{hf:['火','冰'],hfMul:{火:0.25,冰:0.25}},
  '熔岩铠甲':{hf:['水','冰'],hfMul:{水:0.7,冰:0.7}},
  '遇水凝固':{hf:['水'],hfMul:{水:0.5}},
  '夜行':{hf:['恶','妖精'],hfMul:{恶:0.75,妖精:0.75}}
  /* 注：干燥皮肤的火 ×1.25 由 mechRw 机制层（L5118-5125 的 ma.down）负责，不要在这里重复登记，
     否则 opt 会被乘两次（实测 2×1.25×1.25=3.125）。 */
};
var ABI_TAG_CACHE={};
function _abUniq(a){var r=[],i;for(i=0;i<a.length;i++)if(r.indexOf(a[i])<0)r.push(a[i]);return r}
/* 取 id 对应的 [id,en,zh,desc,tags] */
function _abEnt(id){
  var A=ERDATA.abilities;if(!A)return null;
  if(A[id]&&A[id][0]===''+id)return A[id];
  for(var i=0;i<A.length;i++)if(A[i][0]===''+id)return A[i];
  return null;
}
/* 复合特性继承：数据层描述形如「厚脂肪 + 腐蚀.」→ 递归合并基础特性的 im / hf / add。
   这一条修的是系统性缺口：abiTags 不会把「A + B」组合特性的基础标签带上来，
   实测 89 个可解析的复合特性里有 8 个因此丢掉了免疫/减半。 */
function abiTagOf(n,dep){
  dep=dep||0;
  var ck=(dep?'d':'')+'|'+n;
  if(ABI_TAG_CACHE[ck]!==undefined)return ABI_TAG_CACHE[ck];
  var id=NM2ID[n];
  var base=(id&&ERDATA.abiTags)?ERDATA.abiTags[id]:null;
  var o={},k;
  if(base)for(k in base)o[k]=base[k];
  var p=ABI_TAG_PATCH[n];
  if(p){
    if(p.im)o.im=(o.im||[]).concat(p.im);
    if(p.hf)o.hf=(o.hf||[]).concat(p.hf);
    if(p.hfMul){o.hfMul=o.hfMul||{};for(var hm in p.hfMul)o.hfMul[hm]=p.hfMul[hm];}
    if(p.add)o.add=(o.add||[]).concat(p.add);
  }
  if(dep<2&&id){
    var ent=_abEnt(id);
    if(ent&&ent[3]){
      var parts=(''+ent[3]).split('\n')[0].split('+');
      if(parts.length===2){
        for(var q=0;q<2;q++){
          var nm=(''+parts[q]).replace(/[。.\s]/g,'');
          if(!nm||nm===n)continue;
          if(!NM2ID[nm])continue;
          var sub=abiTagOf(nm,dep+1);
          if(!sub)continue;
          if(sub.im)o.im=(o.im||[]).concat(sub.im);
          if(sub.hf)o.hf=(o.hf||[]).concat(sub.hf);
          if(sub.add)o.add=(o.add||[]).concat(sub.add);
        }
      }
    }
  }
  if(o.im)o.im=_abUniq(o.im);
  if(o.hf)o.hf=_abUniq(o.hf);
  var ret=(Object.keys(o).length?o:null);
  ABI_TAG_CACHE[ck]=ret;
  return ret;
}
/* 生效属性：基础属性 + 天性 add（固定）+ 可选池 add（仅提示） */
function effTypesOf(s){
  var base=[];if(s.t1&&s.t1!=='-')base.push(s.t1);if(s.t2&&s.t2!=='-'&&s.t2!==s.t1)base.push(s.t2);
  var inn=[],ab=[];
  s.inns.forEach(function(n){var g=abiTagOf(n);if(g&&g.add)g.add.forEach(function(x){if(base.indexOf(x)<0&&inn.indexOf(x)<0)inn.push(x)})});
  s.abis.forEach(function(n){var g=abiTagOf(n);if(g&&g.add)g.add.forEach(function(x){if(base.indexOf(x)<0&&inn.indexOf(x)<0&&ab.indexOf(x)<0)ab.push(x)})});
  return {base:base,inn:inn,ab:ab};
}
function defMult(types,at){
  var m=1;
  types.forEach(function(dt){var v=ERDATA.matchup[tIdx(dt)][tIdx(at)];
    if(v===0)m=0;else if(v===0.5||v===3)m*=0.5;else if(v===2)m*=2;});
  return m;
}
