var _pcPage=1,_pcCur=[],PC_PAGE=50,_pcType='';   /* v4.148 分页状态；v4.150 类型过滤 */
function savPcPage(d){_pcPage+=d;savPcListRender(_pcCur)}
function savPcGo(v){var n=parseInt(v,10);if(isNaN(n))return;var M=Math.max(1,Math.ceil(_pcCur.filter(function(x){return /^BOX/.test(x.r.来源)}).length/PC_PAGE));n=Math.max(1,Math.min(n,M));_pcPage=n;savPcListRender(_pcCur)}
function savPcListRender(rows){
  _pcCur=rows||[];
  var boxN=_pcCur.filter(function(x){return /^BOX/.test(x.r.来源)});
  var spcN=_pcCur.filter(function(x){return x.r.来源.indexOf('特殊区')===0});
  var h='';
  var M=Math.max(1,Math.ceil(boxN.length/PC_PAGE));
  if(_pcPage<1)_pcPage=1;if(_pcPage>M)_pcPage=M;
  var p=_pcPage;
  if(boxN.length){
    var pg=boxN.slice((p-1)*PC_PAGE,p*PC_PAGE);
    var nav='<span style="display:inline-flex;gap:4px;align-items:center;margin-left:6px;font-size:14px">'+
      '<button class="btn-mini" style="font-size:14px" '+(p<=1?'disabled':'')+' onclick="savPcPage(-1)">‹</button>'+
      '<input type="number" min="1" max="'+M+'" value="'+p+'" style="width:30px;font-size:14px;text-align:center;padding:1px 2px;border:1px solid var(--line);border-radius:4px" onkeydown="if(event.key===\'Enter\')savPcGo(this.value)" onblur="savPcGo(this.value)"> / '+M+' 页'+
      '<button class="btn-mini" style="font-size:14px" '+(p>=M?'disabled':'')+' onclick="savPcPage(1)">›</button></span>';
    h+='<div class="dim" style="font-size:14.5px;padding:2px 4px">电脑区（'+boxN.length+'，点＋入队）'+nav+'</div>'+pg.map(function(x){return savPcRowHtml(x.r,x.i)}).join('');
  }
  if(spcN.length)h+='<div class="dim" style="font-size:14.5px;padding:4px 4px 2px">特殊区·设施预设（'+spcN.length+'，＋入队调优；一键入队见上方橙色按钮）</div>'+spcN.map(function(x){return savPcRowHtml(x.r,x.i)}).join('');
  if(!h)h='<div class="dim" style="padding:6px">无匹配</div>';
  var el=$('savPcList');if(el)el.innerHTML=h;
}
