    var gT=document.createElement('span');gT.style.flex='1;min-width:0';gT.textContent='首次使用：粘贴 CSV → 点「导入」（前 6 只入队）';
    var gX=document.createElement('span');gX.textContent='×';gX.className='sgx';gX.style.cssText='cursor:pointer;font-size:14px;color:var(--sub);flex:none';
    g.appendChild(gT);g.appendChild(gX);
