function renderAbi(){
  var q=$('abiSearch').value.trim();
  var box=$('abiResult');
  var _open=[];   /* v4.41：先记住已展开的卡（按特性 id），重渲染后原样恢复——避免「一切开关就全收起」 */
  if(box)Array.prototype.forEach.call(box.querySelectorAll('.abicard'),function(c){
    var mn=c.querySelector('.abimain');
    if(mn&&mn.style.display==='block')_open.push(''+((c.dataset&&c.dataset.abid)||''));
  });
  box.innerHTML='';
  var cnt=0,_hidN=0,own=abiOwners();
  ERDATA.abilities.forEach(function(a){
    var zh=a[2]||'',en=a[1]||'',desc=abiDescZhOf(a[0]);
    if(a[0]==='0')return;
    /* v4.40：搜索词 = 某规范名/别名时，其**全部**候选 id 的卡都算命中（同名特性 1/808 两卡都出）；
       只在原匹配之外加命中，绝不减少（既有搜索行为零回归）。 */
    if(!fzAny(q,[a[0],zh,en,desc])&&!(q&&abiIdList(q).indexOf(''+a[0])>=0))return;
    if(cnt>=60)return;
    cnt++;
    /* v4.41：持有者列表按本区块开关过滤（标题徽标「可选 N / 天性 N」与两列列表同源，故数字随过滤变化） */
    var _g0=own[a[0]]||{ab:[],inn:[]};
    /* v4.252：判断「数据层真的没有任何物种拥有」，与「被开关过滤成 0」区分 */
    var _zeroAll=(_g0.ab.length===0&&_g0.inn.length===0);
    var grp={ab:lkFilter(_g0.ab,optAbiFinal,optAbiMega),inn:lkFilter(_g0.inn,optAbiFinal,optAbiMega)};
    _hidN+=(_g0.ab.length-grp.ab.length)+(_g0.inn.length-grp.inn.length);
    var tl=[];
    try{tl=abiTagLines(a[0])}catch(e){tl=[];console.warn('abiTagLines('+a[0]+')',e)}var _src=[];try{_src=abiSrcBrief(a[0])}catch(e){_src=[]}
    var card=document.createElement('div');card.className='abicard';
    card.style.cssText='border:1px solid var(--line);background:var(--card);border-radius:10px;padding:10px;margin-bottom:8px;cursor:pointer';
    /* F⑪ 交互：标题行 + 「点击展开」提示均在 .abihd 内；整卡可点（含留白），详情区/按钮内点击不切换 */
    card.innerHTML='<div class="abihd" style="cursor:pointer"><b>'+esc(zh||en)+'</b> <span style="font-size:13.5px;color:var(--sub)">'+esc(en)+' #'+a[0]+'</span>'+
      '<span class="badge badge-res" style="float:right">可选 '+grp.ab.length+'</span><span class="badge badge-imm" style="float:right;margin-right:4px">天性 '+grp.inn.length+'</span>'+
      (_zeroAll?'<span class="badge" style="float:right;margin-right:4px;background:#c0392b;color:#fff">本作无人拥有</span>':'')+
      '<div class="mini" style="color:var(--sub);margin-top:4px;clear:both">'+esc(desc.slice(0,120))+(desc.length>120?'…':'')+' <span style="color:var(--accent)">（点击展开详情卡）</span></div></div>'+
      '<div class="abimain" style="display:none">'+
        '<div class="sec" style="margin:8px 0"><h3>中文描述</h3><div style="font-size:14.5px;line-height:1.95">'+glossify(desc||'（无中文描述）')+'</div></div>'+
        '<div class="sec" style="margin:8px 0"><h3>特性效果（战斗意义）</h3><div style="font-size:14.5px;line-height:1.9">'+
          (tl.length?tl.map(function(x){return '• '+esc(x)}).join('<br>'):'<span style="color:var(--sub)">（数据层未登记标签，以下方「计算倍率」为准）</span>')+'</div></div>'+
         '<div class="sec" style="margin:8px 0"><h3>计算倍率（工具真正计入伤害的部分）</h3><div style="font-size:14.5px;line-height:1.9">'+
           (_src.length?_src.map(function(x){return '• '+esc(x)}).join('<br>'):'<span style="color:var(--sub)">（不在计算类判定表中：属速度 / 回合 / 命中 / 换场类效果，不产生伤害倍率；速度类见「速度线」页）</span>')+'</div></div>'+
        '<div class="sec" style="margin:8px 0"><h3>持有者（分两列：可选池 / 天性固定）</h3>'+(_zeroAll?'<div style="font-size:14.5px;line-height:1.75;color:#c0392b;margin:6px 0 8px">本作没有任何宝可梦拥有这个特性。源码里有它的实现，但没有分配给任何物种，所以配队、特性反查、速度线、伤害面板都不会出现它。</div>':'')+'<div class="abicol">'+
          abiOwnerCol('作为特性（可选池）',grp.ab)+abiOwnerCol('作为天性（固定）',grp.inn)+'</div></div>'+
      '</div>';
    card.onclick=function(ev){
      var t=ev&&ev.target;
      if(t&&t.closest&&(t.closest('.abimain')||t.closest('button')||t.closest('select')||t.closest('input')))return;
      abiToggle(card);
    };
    var hd=card.querySelector('.abihd');
    if(hd)hd.onclick=function(ev){ /* 兜底：即使事件委托失效，标题行本身也能切换 */
      var t=ev&&ev.target;
      if(t&&t.closest&&(t.closest('.abimain')||t.closest('button')))return;
      abiToggle(card);if(ev&&ev.stopPropagation)ev.stopPropagation();
    };
    if(card.dataset)card.dataset.abid=''+a[0];   /* v4.41 修正 1：改用 dataset（verify_v1 打桩 DOM 无 setAttribute） */
    if(_open.indexOf(''+a[0])>=0)abiToggle(card,true);   /* v4.41：恢复重渲染前的展开态 */
    card.querySelectorAll('.mxrow[data-sid]').forEach(function(el){
      el.onclick=function(){var s=speciesById(el.dataset.sid);if(s)openSp(s)};
    });
    box.appendChild(card);
  });
  /* 注意：这里必须用 DOM 追加（appendChild）而不是对容器 innerHTML 做自增重解析——重解析会重建
     全部子节点，把上面逐卡绑定的 card.onclick / hd.onclick / 持有者卡 onclick 全部丢掉
     （用户实测「点特性无效果」根因）。断言 verify_v4 会检查本函数内不出现自增重解析。 */
  if(!cnt)box.innerHTML='<div style="color:var(--sub)">无匹配特性</div>';
  else if(cnt>=60){
    var note=document.createElement('div');
    note.style.cssText='color:var(--sub);text-align:center;padding:8px';
    note.textContent='已显示前 60 个匹配，请细化关键词';
    box.appendChild(note);
  }
  /* v4.41：开关条就地统计（匹配卡数 + 被开关隐藏的持有者条目数） */
  var _st=$('abiFiltStat');
  if(_st)_st.textContent='匹配 '+cnt+' 个特性 · 开关隐藏 '+_hidN+' 个持有者条目';
}
/* F⑪：特性详情卡展开/收起（返回展开态；force=true 展开 / false 收起） */
function abiToggle(card,force){
  if(!card)return false;
  var m=card.querySelector('.abimain');if(!m)return false;
  var open=(typeof force==='boolean')?force:(m.style.display==='none');
  m.style.display=open?'block':'none';
  var hd=card.querySelector('.abihd');if(hd)hd.classList[open?'add':'remove']('open');
  return open;
}
function gotoAbi(name){
  $('abiSearch').value=name;renderAbi();switchTab('abi');
}

