  h+='<div style="font-size:13.5px;color:var(--sub);margin-top:8px">慢端 '+mn+' ←── 极速值 ──→ 快端 '+mx+'　柱高=每个速度区间的物种数（共 '+arr.length+' 条）；竖线为分位切点</div></div>';
  var _pb2=(window._spdFilter||{}).bin;
