var _TC_STATMV=null;
function _tcStatMv(){if(_TC_STATMV)return _TC_STATMV;var o={};try{for(var k in MV){var m=MV[k];if(m&&m[4]==="变化"&&m[1])o[m[1]]=1}}catch(eS){o={}}_TC_STATMV=o;return o}
function _tcTypes(){return (ERDATA&&ERDATA.types)?ERDATA.types:[]}
function _tcWkOf(s){var r={},T=_tcTypes(),ts=effTypesOf(s).base;T.forEach(function(tp){try{if(defMult(ts,tp)>1)r[tp]=1}catch(eW){eW.name}});return r}
function _tcImmOf(s){var r={},T=_tcTypes(),ts=effTypesOf(s).base;T.forEach(function(tp){try{if(defMult(ts,tp)===0)r[tp]=1}catch(eI){eI.name}});return r}
/* v4.284：入场税——按岩石相性算隐形岩、按地面免疫算一层撒菱，纯理论值 */
function _tcTaxOf(s){
  var r={sr:0,spk:0};
  try{
    var ts=effTypesOf(s).base;
    var rm=defMult(ts,"岩石");
    if(rm>0)r.sr=Math.min(0.5,0.25*rm);
    var gm=defMult(ts,"地面");
    if(gm>0)r.spk=0.125;
  }catch(eTx){eTx.name}
  return r;
}
/* v4.285：把体检卡的每条硬伤接上可执行动作——候选按「它自己顶不顶得住岩钉」排 */
/* v4.287：候选带上「照抄就能上场」的配置——特性/道具/性格/EV + 要换的是第几槽 */
/* ===== v4.288：候选池与「我的宝可梦（存档实配）」联动 =====
   用户口径：配队候选要在他**已有**的宝可梦里挑；角色/招式判定按**配置**（存档里这只的四招）判，
   而不是「这只能不能学」。没有解析存档时一切退回全图鉴的老行为。 */
var _OWN_CACHE={rows:null,map:null};
function _ownMap(){
  var rows=(typeof SAV_ROWS!=='undefined'&&SAV_ROWS)?SAV_ROWS:[];
  if(!rows.length)return null;
  if(_OWN_CACHE.rows===rows&&_OWN_CACHE.map)return _OWN_CACHE.map;
  var map={};
  rows.forEach(function(r){
    if(!r||r.图鉴编号==null||r.图鉴编号==='')return;
    var k=String(r.图鉴编号),party=(String(r.来源||'').indexOf('队伍')>=0),cur=map[k];
    if(!cur)map[k]={party:party,row:r};
    else if(party&&!cur.party)map[k]={party:true,row:r};
    else if(!party&&!cur.party&&(+(r.等级||0)>+(cur.row.等级||0)))map[k]={party:false,row:r};
  });
  _OWN_CACHE={rows:rows,map:map};
  return map;
}
function _ownOf(s){var m=_ownMap();return (m&&s&&s.id!=null)?(m[String(s.id)]||null):null}
function _ownMvNames(row){
  if(!row)return [];
  return [row.招式1,row.招式2,row.招式3,row['招式4']]
    .map(function(x){return String(x||'').replace(/\(id=\d+\)$/,'').trim()})
    .filter(function(x){return !!x&&x!=='无'});
}
function _ownSet(s){
  var o=_ownOf(s);if(!o)return null;
  var ns=_ownMvNames(o.row);if(!ns.length)return null;
  var set={};ns.forEach(function(n){set[n]=1});return set;
}
function _ownEvAry(row){return ['EV_HP','EV_攻击','EV_防御','EV_特攻','EV_特防','EV_速度'].map(function(k){return +(row[k]||0)})}
