  var key=String(s.id)+'#'+String(cap||100)+'#'+(_TC_QCTX.link?'L':'')+(_TC_QCTX.dice?'D':'');
  if(_TC_POOLC[key])return _TC_POOLC[key];
  var ids=[],seen={},i,mv,row,t2,mid,ty,bp,eff,pq,isStab;
  var lvs=(s.lv||[]);
  for(i=0;i<lvs.length;i++){
    row=lvs[i];if(!row)continue;
    if(cap&&(+row[0]||0)>cap)continue;
    mid=String(row[1]);
    if(!seen[mid]){seen[mid]=1;ids.push(mid)}
  }
  var tut=(s.tut||[]);
  for(i=0;i<tut.length;i++){t2=String(tut[i]);if(t2&&!seen[t2]){seen[t2]=1;ids.push(t2)}}
  var r={nAtk:0,nRec:0,nSet:0,nPrio:0,nTot:ids.length,nOne:0,recBest:0,recS:'',recA:'',setBest:0,setS:'',prioBest:0,prioTxt:'',cover:0,atkBest:0,atkBestTxt:'',physBest:0,specBest:0};
  var types={};
