var _TC_BWALL={id:-7,zh:'通用高耐久墙',t1:'一般',t2:'一般',base:[108,70,130,70,130,50],abis:[],inns:[]};
var _TC_BWALL_HP=420;
function _tcTtk(tset){
  var out=[];
  (tset||[]).forEach(function(x){
    if(!x||!x.s)return;
    var sp=x.s,phys=(+((sp.base||[])[1]||0))>=(+((sp.base||[])[3]||0));
    var pc=_tcPoolCount(sp,x.L||100);
    var ids=[],seen={},lvArr=(sp.lv||[]),tut=(sp.tut||[]),lim=(x.L||100);
    for(var i=0;i<lvArr.length;i++){if(+lvArr[i][0]<=lim){var m1=String(lvArr[i][1]);if(!seen[m1]){seen[m1]=1;ids.push(m1)}}}
    for(var j=0;j<tut.length;j++){var m2=String(tut[j]);if(!seen[m2]){seen[m2]=1;ids.push(m2)}}
    var best=null;
    for(var k=0;k<ids.length;k++){
      var mv=_tcMvById(ids[k]);
      if(!mv||!(+mv.pw>0))continue;
      if(mv.cat!=='物理'&&mv.cat!=='特殊')continue;
      if(mv.cat==='物理'!==phys)continue;
      if(mv.tags&&mv.tags.indexOf('自爆·退场')>=0)continue;
      if(+mv.pw<20)continue;
      if(String(mv.zh).indexOf('奉还')>=0||String(mv.zh).indexOf('镜面反射')>=0)continue;
      var q=_tcMvEff(mv),fac=q/(+mv.pw||1);
      var abiCtx=[String(x.abi||'')];try{(x.s.inns||[]).forEach(function(z){if(z&&abiCtx.indexOf(z)<0)abiCtx.push(z)});(x.s.abis||[]).slice(0,3).forEach(function(z){if(z&&abiCtx.indexOf(z)<0)abiCtx.push(z)})}catch(eA2){eA2.name}
      var boost=_tcAbiBoostOf(mv,abiCtx);
      try{var dm=dmgCalc({sA:sp,sD:_TC_BWALL,moveId:+ids[k],evA:(x.ev?+x.ev[phys?1:3]:0),natA:(''),evD:252,natD:(phys?'淘气':'温和'),itemA:(x.it||'')});if(!dm)continue;
        var am=+(dm.atkMul||1);if(!(am>0))am=1;
        var avg=((dm.lo+dm.hi)/2)*fac*(boost/am);if(avg<=0)continue;
        var ttk=Math.ceil(_TC_BWALL_HP/avg);
        if(!best||ttk<best.ttk||(ttk===best.ttk&&Math.round(avg)>best.dmg))best={ttk:ttk,mv:mv.zh,dmg:Math.round(avg),q:q};
      }catch(eD){eD.name}
    }
    if(best)out.push({zh:x.zh,mv:best.mv,ttk:best.ttk,dmg:best.dmg});
  });
  out.sort(function(a,b){return a.ttk-b.ttk||b.dmg-a.dmg});
  return {list:out,best:out.length?out[0].ttk:0};
}
var _TC_REFDEF={id:-13,zh:'基准受击者',t1:'一般',t2:'一般',base:[90,90,90,90,90,90],abis:[],inns:[]};
