function mvIsContact(id){return !!MV_CONTACT[''+(id*1)]}
function dmgCondHit(when,sD,sA,mType,isPhys,o,eff){
  if(!when)return false;
  if(/物理招式/.test(when))return isPhys;
  if(/特殊招式/.test(when))return !isPhys;
  if(/满血时/.test(when))return true;          /* 静态分析按满血假设（最不利） */
  if(/效果绝佳/.test(when))return eff>=2;
  if(/会心/.test(when))return !!o.crit;
  if(/沙暴/.test(when))return o.weather==='沙暴';
  if(/冰雹|雪天/.test(when))return o.weather==='雪'||o.weather==='冰雹';
  if(/接触招式/.test(when))return mvIsContact(o&&o.moveId);
  if(/声音招式/.test(when))return mvHasFlag(o&&o.moveId,'sound');   /* v4.232 庞克摇滚防守侧 */
  if(/咬类招式/.test(when))return mvHasFlag(o&&o.moveId,'jaw');
  if(/反作用招式/.test(when))return mvHasFlag(o&&o.moveId,'reckless');
  if(/场地类招式/.test(when))return mvHasFlag(o&&o.moveId,'field');
  if(/(\S+?)属性招式/.test(when)){
    var mt=when.match(/(\S+?)属性招式/)[1];
    return mType===mt;                       /* 招式属性（非攻方属性） */
  }
  if(/攻方是(\S+?)属性/.test(when)){
    var t=when.match(/攻方是(\S+?)属性/)[1];
    return !!(sA&&(sA.t1===t||sA.t2===t));
  }
  return false;                                 /* 认不出的条件不计 */
}
/* 防守方的非属性减伤总倍率（不分属性的 × 条件型），1 表示没有命中任何一条 */
function dmgDefAbiMul(sD,sA,mType,isPhys,o,eff){
  var m=1,hit=[];
  try{
    var names=dmgDefAbis(sD);
    names.forEach(function(n){
      var v=ABI_DMG_ALL[n];
      if(v!==undefined&&v>0){m*=v;hit.push(n+'×'+v)}
      var cs=ABI_DMG_COND[n];
      if(cs)cs.forEach(function(c){
        if(!dmgCondHit(c.when,sD,sA,mType,isPhys,o,eff))return;
        m*=c.mul;hit.push(n+'×'+c.mul+'('+c.when+')');
      });
      /* v4.224：ABI_DMG_MOD（15 条按属性的固定受伤倍率）此前**只被详情卡读取**，一点没进 dmgCalc。
         接进来的同时必须排除两类别重复乘：
           ① ABI_TAG_PATCH 里已登记的 11 条 → 相性层 defCellTrio 已经把 opt() 乘过了；
           ② 干燥皮肤 → mechRw 机制层的 ma.down 已把 opt 乘了 ×1.25（v4.211 实测 2×1.25×1.25=3.125 的教训）。
         其余（超净/免疫/化石化/厚脂肪/原木/坚实基础/洁净之盐/深度冻结/耐热/重金属）机制层实测为空，可安全接入。 */
      var dmr=(typeof ABI_DMG_MOD!=='undefined')?ABI_DMG_MOD[n]:null;
      if(dmr&&!(ABI_TAG_PATCH&&ABI_TAG_PATCH[n])&&n!=='干燥皮肤'){
        dmr.forEach(function(x){
          if(!x.t||x.t.indexOf(mType)<0)return;
          m*=x.mul;hit.push(n+'·'+mType+'×'+x.mul);
        });
      }
    });
  }catch(e){}
  return {mul:m,hits:hit};
}
function dmgCalc(o){
  var mv=ERDATA.moves[o.moveId];if(!mv||!(+mv[5]>0))return null;
  var bp=+mv[5],mType=mv[3],split=mv[4],isPhys=(split==='物理');
  /* v4.180 评估修复：HITS_DEF 分支。split 是 7 值枚举（物理/特殊/变化/取最高攻/取防御/取最高伤害/取特防），
     此前只用 isPhys 二分，导致「特殊但按物防结算」的 4 招（精神冲击473/精神击破540/神秘之剑548/魔法叶345）
     误用特防结算，实测对卡比兽偏低约 35%。 */
  var hitsDef=(split==='特殊(取防御)');
  var sA=megaFormOf(o.sA,o.itemA),sD=o.sD;
  var aIdx=isPhys?1:3, dIdx=hitsDef?2:(isPhys?2:4);
  var A=dmgStatOf(bstI(sA,aIdx),o.evA||0,31,aIdx,o.natA);
  var D=dmgStatOf(bstI(sD,dIdx),o.evD||0,31,dIdx,o.natD);
  var base=Math.floor(Math.floor(42*bp*A/D)/50)+2;
  var mod=1;
  var stab=(mType===sA.t1||mType===sA.t2);   /* STAB：本系或 -ate 转换后本系（ABI_ATE.stabConvert） */
  if(!stab){try{var cv=convOf(sA);if(cv&&cv.to===mType)stab=ABI_ATE.stabConvert!==false}catch(e){}}
  if(stab)mod*=1.5;
  /* v4.214：第三参传 undefined（而不是 null）→ 走 defCellTrio 的全局 teamInfo 分支，
     与属性克制页/弱点表用同一口径（防御方若在队伍里且勾了可选特性，伤害判定同样认）。
     注意：sD 是「对手」，通常不在 teamInfo 里，此时行为与传 null 完全一致。 */
  var eff=1;try{eff=defCellTrio(sD,mType,undefined,(o&&o.weather)||'').opt}catch(e){eff=1}   /* 克制×特性免疫/减半：唯一真值源 */
  if(eff===0)return {lo:0,hi:0,eff:0,stab:stab};
  mod*=eff;
  /* 防守方非属性减伤（多鳞/毛皮大衣/冰鳞粉/棱镜毛皮…，共 40+ 条）——
     不进 ERDATA.matchup 相性表（与属性无关），但真实伤害必须算，否则 OHKO 判定偏高 */
  var abiMul=1,abiHit=[];
  try{var _dm=dmgDefAbiMul(sD,sA,mType,isPhys,o,eff);abiMul=_dm.mul;abiHit=_dm.hits;}catch(e){}
  if(abiMul!==1)mod*=abiMul;
  /* 进攻侧属性增伤（飘浮飞行×1.25 / 水泡水×2 / 电晶体电×1.5 …） */
  var atkMul=1,atkHit=[];
  try{var _am=dmgAtkAbiMul(sA,mType,(o&&o.weather)||'',(o&&o.moveId)||0,{isPhys:isPhys,spec:(split==='特殊'||split==='特殊(取防御)'),pow:bp,contact:mvIsContact((o&&o.moveId)||0),eff:eff,crit:!!(o&&o.crit),stA:(o&&o.stA)||'',tgt:(o&&o.tgt)||''});atkMul=_am.mul;atkHit=_am.hits;}catch(e){}
  if(atkMul!==1)mod*=atkMul;
  if(o.weather==='晴'&&mType==='火')mod*=(1+WCONF.boost);   /* 天气单档（WCONF.boost=0.5 → ×1.5） */
  if(o.weather==='雨'&&mType==='水')mod*=(1+WCONF.boost);
  /* v4.91 任务B：场地 boost 接线（WCONF.terrainBoost=1.3 考古定稿；薄雾=龙系减伤×0.5）。
     沙/雪 在 ER 为防御向（WCONF 口径注释：无伤害档）→ MOD 不加乘，仅 UI 可选标注。 */
  if(o.terrain==='电气'&&mType==='电')mod*=WCONF.terrainBoost;
  if(o.terrain==='青草'&&mType==='草')mod*=WCONF.terrainBoost;
  if(o.terrain==='精神'&&mType==='超能力')mod*=WCONF.terrainBoost;   /* v4.91 复核P2-1：ER 类型名=「超能力」（原误写「超能」死线） */
  if(o.terrain==='薄雾'&&mType==='龙'&&sD&&(sD.t1==='龙'||sD.t2==='龙'))mod*=0.5;   /* v4.91 复核P2-2：ER 口径=龙系招仅对龙系守方×0.5 */
  if(/生命宝珠/.test(o.itemA||''))mod*=1.3;
  if(isPhys&&/讲究头带/.test(o.itemA||''))mod*=1.5;
  if(!isPhys&&/讲究眼镜/.test(o.itemA||''))mod*=1.5;
  if(o.crit)mod*=2;
  return {lo:Math.floor(base*mod*0.85),hi:Math.floor(base*mod),eff:eff,stab:stab,base:base,mod:mod,abiMul:abiMul,abiHit:abiHit,atkMul:atkMul,atkHit:atkHit};
}
/* 反解：evA 从 0 按 4 步递增，首个 min-roll ≥ 对手HP 的 EV（OHKO 线） */
/* v4.95 A：耐久反推——给定威胁(o)与存活次数 N，求最省 EV(HP+单防)。
   算法：HP EV 升序(0..252 step4) 外层、单防 EV 升序内层；首个「hi-roll × N ≤ 当前 HP」组合即最省（HP 优先协调折线）。 */
