function sysDimRule(arch,dim){
  var a=SYS_DIM_RULE[arch];
  return (a&&a[dim])||SYS_RULE_SHARED[dim]||'按维度权重表逐项判定（详见交付报告《v4.x 推荐评分体系化》）';
}
/* ==================================================================================
   v4.36 B（P1·核心动作）：战术模板下沉 —— 引擎侧槽位模型（触发判定 + 组成 + 维度行）
   规格：《ER配招助手_v4.36_个性化亮点强化设计书》§2（T-19~T-30）/ §5.1 闸门；
   TEMPLATES 数据层**不动**（build_tool_data.py / data.js 零改动），与 TPL_EXTRA 同一兜底模式：
   引擎侧数组 TPL_NEW，由 tplAll() 正向追加（低分只排后、不剔除）。
   每条 = trigger(s)（触发判定，用于命中统计与卡片展示）+ slots[]（槽位模型=组成）+ dims[]（维度行=打分）。
   noSysGate=true → 不做「体系主题榜」硬过滤，改由维度行排序（符合「不设死板规则/硬性剔除」）。
   archKey 在 SYS_DIMS 注册新体系键，使维度行可解释、可被 sysTable/sysDimRule 复用。
   src：设计书附录 A 检索 URL；无外部惯例者标「ER 特色发散」。
   ================================================================================== */
var TPL_NEW=[];
var TPL_NEW_RULE={};
function tplAbiHit(s,nm){return (s.abis||[]).concat(s.inns||[]).some(function(n){return abiSame(n,nm)})}
function tplTerrainSetter(s){return (s.abis||[]).concat(s.inns||[]).some(function(n){var v=null;try{v=abiSetExt(n)}catch(e){}return !!v&&/场地|电场/.test(v)})}
function tplBase(s,i){return (s.base&&s.base[i])||0}
function tplBulk(s){return tplBase(s,0)+tplBase(s,2)+tplBase(s,4)}
function tplLearnN(s,ids){var n=0;ids.forEach(function(id){if(learnHasAnyId(s,[id]))n++});return n}
var TPL_IMM_ABI=['引水','避雷针','储水','食草','电气引擎'];
var TPL_SELFDROP=['近身战','蛮力','流星群','过热','飞叶风暴','精神突进'];
function tplNew(o){
  var t={name:o.name,theme:o.theme,roles:o.roles||[],keys:o.keys||[],
    match:o.match||{abis:[],moves:[],types:[]},counters:o.counters||{types:[]},
    flow:o.flow||[],
    tips:(o.tips||[]).concat(['引擎侧模板下沉（v4.36；数据层 TEMPLATES 未改动，低分只排后不剔除）']),
    archKey:o.arch,dims:o.dims,trigger:o.trigger,slots:o.slots||[],trigTxt:o.trigTxt||'',
    src:o.src,sysList:o.sysList||[],noSysGate:true,tplNewVer:o.ver||'v4.36'};
  SYS_DIMS[o.arch]=o.dims.concat([SIDE_DIM]);
  SYS_DIM_RULE[o.arch]=o.rules||{};
  TPL_NEW.push(t);return t;
}
