/* B9 分层5：4 招对 21 属性取「最优倍率」（max）→ 盲点=全部 ≤0.5x 的属性 */
function setCoverProfile(s,ids,conv){
var prof={};
/* v4.193：攻击方自己的相性改写特性（源码 gAbilities[].onTypeEffectiveness 挂的是 battlerAtk）
   例：带「地面冲击」→ 自己的电招打地面从「无效 0」变成「抵抗 0.5」；带「腐蚀」→ 毒打钢从 0 变 2 */
var abn=(s&&s.inns)?s.inns.slice():[];
/* 勾选的可选特性（teamInfo.pick）同样参与相性改写，与 defCellTrio 的 opt 口径一致；
   否则带「地面冲击」的宝可梦勾上后，打击面仍按电打地面=无效 算 */
try{var _pi=teamInfo[s.id];if(_pi&&_pi.pick&&abn.indexOf(_pi.pick)<0)abn.push(_pi.pick);}catch(e){}
var selfT=null;
ERDATA.types.forEach(function(at){
var mx=0;
ids.forEach(function(id){
var m=MV[id];if(!m)return;
var ty=effMvType(s,m,conv);
var v=ERDATA.matchup[tIdx(at)][tIdx(ty)];
var val=(v===0?0:((v===0.5||v===3)?0.5:(v===2?2:1)));
if(abn.length){
  if(!selfT){selfT=[];if(s.t1&&s.t1!=='-')selfT.push(s.t1);if(s.t2&&s.t2!=='-')selfT.push(s.t2);}
  for(var q=0;q<abn.length;q++){val=abiTeApplyOne(abn[q],ty,at,val,selfT,m[1]);}
}
if(val>mx)mx=val;
});
prof[at]=mx;
});
return prof;
}
function blindList(prof){
  var out=[];ERDATA.types.forEach(function(at){if(prof[at]<1)out.push(at)});return out;
}
function whyHtml(why){
  if(!why||!why.length)return '';
  return why.map(function(x){return esc(x)}).join(' × ').replace(/ × ⚠/g,'　⚠');
}
