  '速攻':{轮转:13,状态:9,钉子:8,回复:7,盾:6,天气手:5,输出:2},
  '增伤':{天气手:12,钉子:9,盾:8,回复:8,轮转:7,状态:6,输出:2},
  '肉盾':{状态:14,回复:13,钉子:11,轮转:7,盾:7,天气手:4,输出:1},
  '受队':{状态:15,回复:13,钉子:11,轮转:7,盾:6,天气手:3,输出:1},
