/* v4.35 P1-5 亮点门槛（AP4/AP9 治理）：
   · 撒钉除钉(hazard_removal) 降级为「基础保障」，不计入组合亮点（全库 ~95% 队伍恒命中 → 退化为噪声）；
   · src 必填（无检索来源的条目不作亮点）；
   · 亮点须**体系/核心强相关或三方协同**（核心在参与者里 / 参与方 ≥3 / 组合体系属核心体系）；
   · 参与方必须**实际配招**支持该组合（strict 口径：按真实装配的 4 招校验）。 */
var COMBO_SYS={rain_thunder:'雨',rain_swim:'雨',tr_rain:'雨',sand_rock:'沙',snow_veil:'雪'};
var COMBO_STRICT={
  prank_weather:function(mem,mvOf){for(var i=0;i<mem.length;i++)for(var j=0;j<mvOf[i].length;j++)if(FUNC_MV.weather.indexOf(mvOf[i][j])>-1)return true;return false},
  slow_pivot_weather:function(mem,mvOf){return COMBO_STRICT._pivot(mem,mvOf)},
  rain_thunder:function(mem,mvOf){for(var i=0;i<mem.length;i++)if(mvOf[i].indexOf(87)>-1||mvOf[i].indexOf(542)>-1)return true;return false},
  tr_rain:function(mem,mvOf){for(var i=0;i<mem.length;i++)if(mvOf[i].indexOf(433)>-1)return true;return false},
  snow_veil:function(mem,mvOf){for(var i=0;i<mem.length;i++)if(mvOf[i].indexOf(657)>-1)return true;return false},
  toxic_orb_pivot:function(mem,mvOf){return COMBO_STRICT._pivot(mem,mvOf)},
  _pivot:function(mem,mvOf){for(var i=0;i<mem.length;i++)for(var j=0;j<mvOf[i].length;j++)if(FUNC_MV.pivot.indexOf(mvOf[i][j])>-1)return true;return false}
};
/* 队伍组合扫描：members=[{s,core?,priRole?}]，命中组合 → [{id,name,cat,parts,note,src}]（≤4 条，按 cat 去重保首条）
   opts.strict=true → 启用 v4.35 P1-5 亮点门槛（展示层用；排序期仍走轻量口径以保性能） */
function scanCombos(members,opts){
  var strict=!!(opts&&opts.strict);
  var out=[],seenCat={};
  try{
    var mem=(members||[]).filter(function(m){return m&&m.s});
    if(mem.length<2)return out;
    var coreS=null;mem.forEach(function(x){if(x.core)coreS=x.s});
    var coreSysList=[];try{coreSysList=coreS?coreSys(coreS):[]}catch(e0){coreSysList=[]}
    var teamArr=(coreS?[coreS]:[]).concat(mem.filter(function(x){return !x.core}).map(function(x){return x.s}));
    var mvOf=null;
    if(strict){
      mvOf=[];
      for(var i=0;i<mem.length;i++){
        var ids=[];
        try{
          if(mem[i].core){var bs=deriveBuilds(mem[i].s);ids=(bs&&bs[0]&&bs[0].mv&&bs[0].mv.main)?bs[0].mv.main.map(function(sl){return sl.id}):[]}
          else{var asm=mateAssemble(mem[i],teamArr,coreSysList);ids=((asm&&asm.moves)||[]).map(function(m2){return m2.id})}
        }catch(e1b){ids=[]}
        mvOf.push(ids);
      }
    }
    MECH_COMBO.forEach(function(c){
      if(out.length>=4)return;
      if(strict&&c.id==='hazard_removal')return;  /* P1-5：降级为基础保障，不计亮点 */
      if(strict&&!c.src)return;                   /* P1-5：src 必填 */
      var r=null;try{r=c.check(mem)}catch(e2){r=null}
      if(!r||!r.parts||!r.parts.length)return;
      if(seenCat[c.cat])return;
      if(strict){
        var inParts=!!(coreS&&r.parts.indexOf(coreS.zh)>-1);
        var csy=COMBO_SYS[c.id]||'';
        var rel=inParts||r.parts.length>=3||(!!csy&&coreSysList.indexOf(csy)>-1);
        if(!rel)return;                           /* P1-5：体系/核心强相关或三方协同 */
        var vf=COMBO_STRICT[c.id];
        if(vf&&mvOf){var ok=false;try{ok=vf(mem,mvOf)}catch(e3b){ok=false}if(!ok)return}  /* P1-5：参与方实际配招 */
      }
      seenCat[c.cat]=1;
      /* v4.32 P1-4：参与者去重——同一只宝可梦不得占两个参与位（阿尔宙斯-幽灵×2 / 超级帝王拿波×2） */
      var parts=[],seenP={};
      (r.parts||[]).forEach(function(p){if(!seenP[p]){seenP[p]=1;parts.push(p)}});
      out.push({id:c.id,name:c.name,cat:c.cat,parts:parts,note:r.note,src:c.src});
    });
  }catch(e3){}
  return out;
}
/* 组合亮点渲染（纯展示：组合名+参与者+说明+来源；ER 特有标注橙色） */
function comboHtml(combos){
  if(!combos||!combos.length)return '';
  var h='<div class="sec" style="margin:8px 0;background:var(--section-bg);border-color:var(--section-border)"><h3>✨ 组合亮点（'+combos.length+'）</h3>';
  combos.forEach(function(c){
    h+='<div style="font-size:14.5px;margin:4px 0;padding:5px 8px;background:var(--card);border-radius:6px;border-left:3px solid '+
      (c.cat==='ER特有'?'#f59e0b':'#38bdf8')+'">'+
      '<b>'+esc(c.name)+'</b> <span class="mtag '+(c.cat==='ER特有'?'sys':'def')+'">'+esc(c.cat)+'</span> · 参与：'+
      esc(c.parts.join(' + '))+'<br><span style="color:var(--sub);font-size:13.5px">'+esc(c.note)+
      (c.src?('　<a href="'+esc(c.src)+'" target="_blank" style="color:var(--acc)">来源↗</a>'):'')+'</span></div>';
  });
  return h+'</div>';
}
/* D8：名称前缀（形态折叠键）—— '阿尔宙斯-毒' → '阿尔宙斯'；'雷电云-灵兽形态' → '雷电云' */
function prefixKey(s){return String(s.zh||'').split(/[-（(·]/)[0]}
/* ==================================================================================
   v4.2 阶段 3：正向体系构建 buildTeam —— 槽位模型
   权威规格：docs\战斗分析\07_组队方法论.md（§2.0 骨架总表 / §3.1 D1–D18 / §3.2 槽位×维度矩阵 /
   §4.3 SLOT_TABLE / §4.4 buildTeam 契约）。

   用户裁定（方法论核心批评）：「配队是正向的，队伍 = 天气手 + 速攻核心 + 弱点补盲 + 联防 + 撒钉 +
   轮转的系统，不是 6 个强个体」「否定硬互斥剔除 / 硬排除 / 红框这类负向思维」。
   ⇒ 本层完全正向：**零硬门、零否决、得分恒 ≥ 0**。
      · 只保留「角色必要条件」= 这只能不能干这个槽位的活（设置手槽必须能开体系、物盾槽必须 base[def]≥100
        …），这属于**正向定位**，不是「不够强就剔除」；
      · 不达标者得 0 分 / 低分排后，**仍出现在该槽位的备选列表**（铁证：龙头地鼠速度 88 → 空间打手槽
        低速线 +0 → 排后但可见，不出现「硬排除」字样）；
      · 偏差登记 D-1：文档 §1.5/§4.4 把 `wxConflict` 列为「唯一硬门、保留」，**用户本轮明确要求移除硬互斥
        ⇒ 以用户指令为准**；`wxConflict/wxSetOf` 已删除，对立体系靠体系受益分自然排后（详见交付报告 §v4.2）。
   ================================================================================== */
/* 体系字段域（天气 4 + 场地 4 + 剧毒场地）：S-SET 门用它判定「是否体系设置手」 */
var FIELD_SYS=['雨','晴','沙','雪','电场','精神场地','青草场地','薄雾场地','剧毒场地'];
/* ============ v4.3 阈值（07 §4.5.2：必须可配置，禁止把魔数写进算法正文） ============ */
var NEED_CFG={SPEED_HIGH:100,SPEED_LOW:60,BULK_HIGH:300,BULK_MID:270,MIXED_OK:70,POWER_OK:95,
  MULTI_ROLE_BONUS:3,STOP_PRIORITY:1,MAX_TEAM:6,
  /* v4.45 A-1（设计书 C §3.1 伪码）：λ = 绝对实力项的**折扣系数常量**（不随需求变化）。
     标定依据（设计书 C §9 P5/探针 simulate）：λ=0→41 distinct top-1 / 0.2→43 / **0.35→47** / 0.5→50；
     取 0.35 —— 0.35→0.5 只 +3 distinct，折扣越小对既有排序的扰动越小（λ 是常量，D-5 裁决）。 */
  LAMBDA_GEN:0.50, /* v4.47 A1（任务书 §1 裁决①）：0.35 → 0.50。设计书 C §3.4 λ 标定表：λ=0.50 →
                      mateDistinct 50 / mateMaxShare 20.6% / needCoverage 77.2%（λ=0 基线 41/21.6%/76.9%）。
                      **常量**而非可配置项 —— 保 rsTeamCard 强度校准回退语义（设计书 C D-5）。
                      A-3（分档轮转）本轮**未启用**：P7 复算 plans=0（仪器故障，见实施报告 §1）。 */
  MULTI_MAX:2 /* 单只最多「顺带满足」的额外需求数——07 §4.5.3 未设上限；加此上限以保持 07 期望的 4~6 只队伍，
                 避免一只全能宝可梦一次清零十余条需求导致队伍缩到 2~3 只（实现口径已在交付报告登记） */};
/* ============ v4.8（G2/G3）：目标队伍规模 = 产品级参数（默认 6 / 2 = v4.7 现行为） ============
   依据《引擎规模行为核查_报告》（M4，只读核查）：引擎自身推荐 5.33 人（18 核心实测、无 3 人以下），
   评测口径「3.60」为池构造（删人/随机样本占 95.6%）+ min-size 过滤 + 均值型指标规模偏置的假象；
   反事实：多功能合并上限 =0 → 18/18 恰好 6 只 → 引擎**有能力**稳定满编。
   本轮把两个硬编码常量提升为产品级参数并接入 UI「目标队伍规模」选择：
     · target   ：目标队伍规模 3~6（默认 6）；调小 = **上限收紧**（正向引导，不是硬剔除——候选池仍全量可见）
     · multiMax ：多功能合并上限（默认 2）；目标 ≤4 时自动降为 1（合并更弱 → 队伍不塌到目标人数之下）
     · 补位     ：需求驱动结果不足 target 时，方案卡可手动「继续补位」（按广义正向分取最优，
                  标注「补位（非需求驱动）」）；候选池从不枯竭，补位是正向追加而非放宽否决。
   回退：TEAM_CFG.target=6、multiMax=2、PLAN_FILL 空 → 与 v4.7 行为逐字节一致（RULE_SHIFT 零改动）。 */
var TEAM_CFG={target:NEED_CFG.MAX_TEAM,multiMax:NEED_CFG.MULTI_MAX,TARGET_MIN:3,TARGET_MAX:NEED_CFG.MAX_TEAM,MULTI_BASE:NEED_CFG.MULTI_MAX};
