function multiMaxForTarget(v){v=parseInt(v,10)||TEAM_CFG.TARGET_MAX;return v>=5?TEAM_CFG.MULTI_BASE:Math.max(1,TEAM_CFG.MULTI_BASE-1)}
function planFillOf(coreId){return Math.max(0,PLAN_FILL[''+coreId]||0)}
