      var natSpeed=true;try{var _nn=normNatName((buildObj&&buildObj.nat&&buildObj.nat[0])?buildObj.nat[0][0]:'');if(_nn&&!/(胆小|急躁|爽朗|天真|害羞)/.test(_nn))natSpeed=false}catch(eN){}
