/* v4.11 F1：L2 ⑦ 道具说明「玩家话术」——优先取道具池 ITEM_POOL 的玩家向 why（**既有数据文案**，
   非新编内容），缺失时把引擎串「克制 X；代价 Y｜原则 P…」的包装剥成纯内容。
   引擎原文完整保留在 L3（「道具 why（引擎原文）」），符合「只降级不删除」。 */
function itemPoolNoteOf(zh){
  var out='',z=String(zh||'');
  try{
    (ITEM_POOL||[]).forEach(function(p){
      if(out)return;
      if(p.dynamic){                    /* 动态项：属性宝石（通名含「宝石」）/ 属性减伤果（名以「果」结尾） */
        if(p.dynamic==='gem'&&/\u5b9d\u77f3/.test(z))out=p.why||'';
        else if(p.dynamic==='resist'&&/\u679c$/.test(z))out=p.why||'';
      }else if(p.zh===z)out=p.why||'';
    });
  }catch(eA){}
  return out;
}
function itemNote(zh,why){
  var s=String(why==null?'':why);
  var m=s.match(/\uff1b\u4ee3\u4ef7\s*([^\uff5c]*)/),cost=m?String(m[1]).trim():'';
  var pn=itemPoolNoteOf(zh);
  if(pn){
    /* 代价已含在玩家向说明里（前 2 字重叠）→ 不重复追加 */
    var extra=(cost&&cost.length>=4&&cost!=='\u5360\u9053\u5177\u4f4d\uff0c\u673a\u4f1a\u6210\u672c'&&pn.indexOf(cost.slice(0,2))<0)?('\uff1b\u6ce8\u610f\uff1a'+cost):'';
    return pn+extra;
  }
  return s.replace(/^\s*\u514b\u5236\s*/,'').replace(/\uff5c\u539f\u5219\s*P[^\uff5c]*/,'').replace(/\uff1b\u4ee3\u4ef7\s*/,'\uff1b\u6ce8\u610f\uff1a').trim();
}
/* L2① 玩法一句话（玩家话术：不含百分比 / 倍率式子） */
function oneLiner(bd){
  var tag=String(bd.roleTag||''),side=String(bd.side||'');
  var moves=(bd.mv&&bd.mv.main)||[],mainName='',hasBoost=false,hasRec=false;
  if(moves.length)mainName=String((MV[moves[0].id]||[])[1]||'');
  moves.forEach(function(x){
    if(FUNC_MV.boost.indexOf(x.id)>-1)hasBoost=true;
    if(FUNC_MV.rec.indexOf(x.id)>-1)hasRec=true;
  });
  var how=(tag==='肉盾'||tag==='受队')?'靠耐久压制与消耗慢慢磨':(tag==='天气'?'围绕体系天气把输出拉满':('以'+side+'输出抢节奏'));
  var bits=['这是一条「'+bd.name+'」玩法：'+how];
  if(mainName)bits.push('核心手段是「'+mainName+'」');
  if(hasBoost)bits.push('先手强化后再转输出');
  if(hasRec)bits.push('自带回复所以更耐打');
  return bits.join('，')+'。';
}
