    function _abZh(a){return (a&&a.id!=null&&a.id!==''&&ABI[a.id])?(ABI[a.id][2]||ABI[a.id][1]||('#'+a.id)):((a&&a.n)?abiNameZh(a.n):'—')}   /* v4.52 C5d：回退接 abiNameZh 别名反查 */
